#include <atomic>
#include <iostream>

int main() {
    alignas(std::atomic_ref<unsigned>::required_alignment) unsigned storage{12};
    std::atomic_ref<unsigned> flags{storage}; // Binary 1100
    std::cout << flags.fetch_and(10) << " -> " << flags.load() << "\n";
    std::cout << flags.fetch_or(3) << " -> " << flags.load() << "\n";
    std::cout << flags.fetch_xor(1) << " -> " << flags.load() << "\n";
    flags &= 7;
    flags |= 4;
    flags ^= 1;
    std::cout << flags.load() << "\n";
}
